    "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nmodel User {\n  id               String           @id @default(cuid())\n  email            String?          @unique\n  name             String?\n  firstName        String?\n  lastName         String?\n  nickname         String?          @unique\n  isDefault        Boolean          @default(true)\n  image            String?\n  emailVerified    DateTime?\n  monetizationRole MonetizationRole @default(FREE)\n  workRole         WorkRole         @default(CLIENT)\n  ownedBoards      Board[]          @relation(\"BoardOwner\")\n  boardMemberships BoardMember[]\n  accounts         Account[]\n  comments         Comment[]\n  createdAt        DateTime         @default(now())\n  updatedAt        DateTime         @updatedAt\n}\n\nmodel Board {\n  id          String  @id @default(cuid())\n  title       String\n  description String?\n  logoUrl     String?\n  themeColor  String?\n\n  ownerId String?\n  owner   User?   @relation(\"BoardOwner\", fields: [ownerId], references: [id])\n\n  tickets     Ticket[]\n  columns     BoardColumn[]\n  memberships BoardMember[]\n  roles       BoardRole[]\n  invitations BoardInvitation[]\n  createdAt   DateTime          @default(now())\n  updatedAt   DateTime          @updatedAt\n}\n\nmodel BoardMember {\n  id        String          @id @default(cuid())\n  role      BoardMemberRole @default(MEMBER)\n  boardId   String\n  userId    String\n  board     Board           @relation(fields: [boardId], references: [id], onDelete: Cascade)\n  user      User            @relation(fields: [userId], references: [id], onDelete: Cascade)\n  createdAt DateTime        @default(now())\n  updatedAt DateTime        @updatedAt\n\n  @@unique([boardId, userId])\n  @@index([userId])\n}\n\nmodel BoardRole {\n  id          String   @id @default(cuid())\n  boardId     String\n  board       Board    @relation(fields: [boardId], references: [id], onDelete: Cascade)\n  name        String\n  permissions String[] @default([])\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@unique([boardId, name])\n  @@index([boardId])\n}\n\nmodel BoardInvitation {\n  id        String          @id @default(cuid())\n  email     String\n  boardId   String\n  board     Board           @relation(fields: [boardId], references: [id], onDelete: Cascade)\n  role      BoardMemberRole\n  status    String          @default(\"pending\") // \"pending\" | \"accepted\" | \"declined\"\n  expiresAt DateTime\n  createdAt DateTime        @default(now())\n\n  @@unique([boardId, email])\n  @@index([boardId])\n  @@index([email])\n}\n\nmodel BoardColumn {\n  id       String @id @default(cuid())\n  title    String\n  position Int\n\n  boardId String\n  board   Board    @relation(fields: [boardId], references: [id], onDelete: Cascade)\n  tickets Ticket[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([boardId, position])\n}\n\nmodel Ticket {\n  id String @id\n\n  title       String\n  description String?\n\n  status    String\n  sortIndex Int    @default(0)\n  priority  String\n  type      String\n\n  accessibilityRoles String[] @default([])\n  accessibilityIds   String[] @default([])\n\n  boardId String\n  board   Board  @relation(fields: [boardId], references: [id], onDelete: Cascade)\n\n  columnId String?\n  column   BoardColumn? @relation(fields: [columnId], references: [id], onDelete: SetNull)\n\n  estimateOriginalHours  Int?\n  estimateSpentHours     Int?\n  estimateRemainingHours Int?\n  storyPoints            Int?\n\n  subtasks Subtask[]\n  comments Comment[]\n\n  dueDate   DateTime?\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  @@index([boardId, status, sortIndex])\n  @@index([boardId, columnId, sortIndex])\n}\n\nmodel Subtask {\n  id       String  @id @default(cuid())\n  title    String\n  done     Boolean @default(false)\n  ticketId String\n  ticket   Ticket  @relation(fields: [ticketId], references: [id], onDelete: Cascade)\n}\n\nmodel Comment {\n  id        String   @id @default(cuid())\n  body      String\n  ticketId  String\n  ticket    Ticket   @relation(fields: [ticketId], references: [id], onDelete: Cascade)\n  authorId  String?\n  author    User?    @relation(fields: [authorId], references: [id])\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Account {\n  id                String  @id @default(cuid())\n  userId            String\n  type              String\n  provider          String\n  providerAccountId String\n  refresh_token     String?\n  access_token      String?\n  expires_at        Int?\n  token_type        String?\n  scope             String?\n  id_token          String?\n  session_state     String?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, providerAccountId])\n}\n\nmodel VerificationToken {\n  identifier String\n  token      String   @unique\n  expires    DateTime\n\n  @@unique([identifier, token])\n}\n\nenum BoardMemberRole {\n  OWNER\n  ADMIN\n  MEMBER\n  VIEWER\n}\n\nenum MonetizationRole {\n  FREE\n  SUBMITTED\n  PREMIUM\n}\n\nenum WorkRole {\n  CLIENT\n  EXECUTOR\n  ORGANIZER\n  CEO\n}\n",
